UPDATE participants
SET pin_hash = #{pinHash}, pin_temporary = #{temporary}, updated_at = #{now}
WHERE space_id = #{spaceId} AND event_id = #{eventId} AND id = #{participantId}

UPDATE participants
SET name = #{name}, updated_at = #{now}
WHERE space_id = #{spaceId} AND event_id = #{eventId} AND id = #{participantId}

UPDATE participants
SET phone = #{phone}, phone_hash = #{phoneHash}, phone_last4 = #{phoneLast4},
    phone_key = #{phoneKey}, updated_at = #{now}
WHERE space_id = #{spaceId} AND event_id = #{eventId} AND id = #{participantId}
